"""One card per word, complete.

A flashcard has to stand on its own: you see it, you answer, and what comes back
has to settle the question without sending you to a dictionary. That needs four
things, and the notes supplied roughly one of them.

Each value is a dict:

    id     the Indonesian meaning
    en     the English meaning
    note   why this word and not its neighbour — the thing that is obvious once
           someone tells you and invisible until they do. Register, grammatical
           constraint, the near-synonym it is usually confused with. Written in
           Indonesian, the language the notes think in.
    ex     usage examples, each (chinese, indonesian, english)

Rules the sentences follow:

  - every sentence contains its own word, or the cloze cannot blank it
  - 5 to 20 characters: enough to show the word working, short enough to rebuild
  - built from vocabulary already in this deck, so a sentence never teaches one
    word by way of three unknown ones
  - the examples of a word differ in grammar or situation, not just in nouns —
    two sentences that differ only in their object teach the word once
"""

