# --------------------------------------------------------------------------
# Completing the cards
# --------------------------------------------------------------------------
# The migration above carried over what already existed: two meanings and one
# example with its Indonesian translation. What it could not carry over is what
# was never written — the explanation, the English translation of the example,
# and a second example.
#
# Each entry here is (note, first_example_in_english, second_example) where the
# second example is (chinese, indonesian, english).
#
# The note is the part that does the real work. It is not a restatement of the
# meaning — the meaning is already on the card — but the thing you would have to
# ask a person: which of two near-synonyms this is, where in the sentence it can
# sit, whether it is something you would actually say out loud.

FILL: dict[str, tuple[str, str, tuple[str, str, str]]] = {}


def _apply_fill() -> None:
    for hanzi, (note, first_en, second) in FILL.items():
        card = CARDS.get(hanzi)
        if card is None:
            continue
        card["note"] = note
        zh_line, indonesian, _ = card["ex"][0]
        card["ex"][0] = (zh_line, indonesian, first_en)
        if second and second[0] not in [e[0] for e in card["ex"]]:
            card["ex"].append(second)


